function [d, ls_mjd, ls_dat] = leap_at(ls_mjd, ls_dat, mjd)
%LEAP_AT  TAI - UTC [s] at a UTC MJD from the leap-second file's rows (their MJD and TAI - UTC): the last row at or before it,
%   else the first row's.
%   length: 8
%   ls_mjd: inout real[1][*] (passed a plain number)
%   ls_dat: inout real[1][*] (passed a plain number)
%   mjd: real[1] (passed a plain number)
%   returns d: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    d = 0;
    d = ls_dat(1);
    for i = (0):((numel(ls_mjd)) - 1)
        if (ls_mjd((i) + 1) <= mjd)
            d = ls_dat((i) + 1);
        end
    end
end
